contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 marketSeed, uint256 amount) public payable {
        require(address(this).balance >= amount);
        require(amount > 0);

        c.seedMarket(marketSeed);

        uint256 balBefore = address(c).balance;
        uint256 claimedBefore = c.claimedDrugs(address(this));
        uint256 market = c.marketDrugs();

        // expected purchase computed through the public surface
        uint256 raw = c.calculateTrade(amount, balBefore - amount, market);
        uint256 expectedBought = raw - c.devFee(raw);
        uint256 expectedFee = c.devFee(amount);

        c.buyDrugs{value: amount}();

        uint256 balAfter = address(c).balance;
        uint256 claimedAfter = c.claimedDrugs(address(this));

        assert(
            claimedAfter == claimedBefore + expectedBought
            && balAfter == balBefore + amount - expectedFee
        );
    }

    receive() external payable {}
}

