contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 marketSeed, uint256 amount) public payable {
        require(amount > 0 && amount <= 1 ether);
        require(marketSeed > 0 && marketSeed <= 1000);
        require(address(this).balance >= amount);

        c.seedMarket(marketSeed);

        uint256 claimedBefore = c.claimedDrugs(address(this));
        uint256 balanceBefore = c.getBalance();
        uint256 raw = c.calculateDrugBuySimple(amount);

        c.buyDrugs{value: amount}();

        uint256 claimedAfter = c.claimedDrugs(address(this));
        uint256 balanceAfter = c.getBalance();

        assert(claimedAfter == claimedBefore + raw - c.devFee(raw) && balanceAfter == balanceBefore + amount - c.devFee(amount));
    }

    receive() external payable {}
}

